import { test, expect, type APIRequestContext } from '@playwright/test';

const TINY_PNG = Buffer.from(
  'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==',
  'base64'
);

function makeEmail(prefix: string): string {
  const rand = Math.random().toString(36).slice(2, 7);
  return `${prefix}-${Date.now()}-${rand}@example.com`;
}

async function loginUser(
  request: APIRequestContext,
  email: string,
  nickname: string
): Promise<{ id: string; email: string; nickname: string }> {
  const sendRes = await request.post('/api/auth/send-code', { data: { email } });
  expect(sendRes.status()).toBe(200);
  const sendJson = await sendRes.json();
  const verifyRes = await request.post('/api/auth/verify-code', {
    data: { email, code: sendJson.devCode, nickname },
  });
  expect(verifyRes.status()).toBe(200);
  return (await verifyRes.json()).user;
}

test.describe.serial('发布功能优化与UI改版基础E2E验证', () => {
  test('1. 品牌更名dev社区、三栏布局与吸顶Tab及右侧搜索', async ({ page }) => {
    await page.setViewportSize({ width: 1440, height: 900 });
    await loginUser(page.request, makeEmail('ui-base'), '开发者甲');
    await page.goto('/');

    await expect(page.getByText(/dev社区/i).first()).toBeVisible();
    await expect(page.getByText('轻图文 · 慢生活灵感角落')).toHaveCount(0);
    await expect(page.getByText('把日常瞬间写成光')).toHaveCount(0);

    const latestTab = page.getByRole('tab', { name: /最新/ }).or(page.getByRole('button', { name: /^最新$/ })).first();
    const hotTab = page.getByRole('tab', { name: /最热/ }).or(page.getByRole('button', { name: /^最热$/ })).first();
    const followTab = page.getByRole('tab', { name: /我的关注/ }).or(page.getByRole('button', { name: /我的关注/ })).first();
    await expect(latestTab).toBeVisible();
    await expect(hotTab).toBeVisible();
    await expect(followTab).toBeVisible();

    const rightAside = page.locator('aside').nth(1);
    const searchInput = rightAside.locator('input').first();
    await expect(searchInput).toBeVisible();
  });

  test('2. X.com 无标题发布、正文#话题解析与收藏导航跳转', async ({ page }) => {
    await page.setViewportSize({ width: 1440, height: 900 });
    await loginUser(page.request, makeEmail('compose-base'), '发帖开发者');
    await page.goto('/');

    const tag = `DevTag${Date.now().toString().slice(-4)}`;
    const bodyText = `无标题纯正文发布测试 #${tag} 分享开发心得`;

    const textarea = page.locator('textarea').first();
    await expect(textarea).toBeVisible();
    await expect(page.getByPlaceholder(/标题/)).toHaveCount(0);
    await textarea.fill(bodyText);

    const createPromise = page.waitForResponse(
      (r) => r.url().endsWith('/api/posts') && r.request().method() === 'POST'
    );
    await page.getByRole('button', { name: /发布|发送/i }).first().click();
    const res = await createPromise;
    expect(res.status()).toBe(201);
    const created = await res.json();
    expect(created.post.tags).toContain(tag);

    const card = page.locator('article').filter({ hasText: bodyText }).first();
    await expect(card).toBeVisible();
    await card.getByRole('button', { name: /收藏/i }).first().click();

    const leftAside = page.locator('aside').first();
    await leftAside.getByRole('button', { name: /收藏/ }).or(leftAside.getByRole('link', { name: /收藏/ })).first().click();
    await expect(page.locator('article').filter({ hasText: bodyText }).first()).toBeVisible();
  });

  test('3. 通知红点点击对应分类自动标为已读', async ({ page, browser }) => {
    await page.setViewportSize({ width: 1440, height: 900 });
    const ctxB = await browser.newContext();
    try {
      const userA = await loginUser(page.request, makeEmail('notif-cat-a'), '通知作者A');
      await loginUser(ctxB.request, makeEmail('notif-cat-b'), '互动用户B');

      const pRes = await page.request.post('/api/posts', {
        data: { content: `通知测试动态-${Date.now()}` },
      });
      const postId = (await pRes.json()).post.id;
      await ctxB.request.post(`/api/users/${userA.id}/follow`);
      await ctxB.request.post(`/api/posts/${postId}/like`);
      await ctxB.request.post(`/api/posts/${postId}/comments`, { data: { content: '很棒的分享' } });

      await page.goto('/');
      const leftAside = page.locator('aside').first();
      await leftAside.getByRole('button', { name: /通知/ }).or(leftAside.getByRole('link', { name: /通知/ })).first().click();

      const commentTab = page.getByRole('tab', { name: /评论/ }).or(page.getByRole('button', { name: /评论/ })).first();
      await commentTab.click();
      await expect.poll(async () => {
        const u = await (await page.request.get('/api/notifications/unread-count')).json();
        return u.unreadByType.comment;
      }).toBe(0);
    } finally {
      await ctxB.close();
    }
  });
});
